const OPENNOW_SCRIPT = "<script>\n/* v5.4-open-now */\n\nfunction ytpParseTime54(s){var m=/^(\\d{1,2})(?::(\\d{2}))?\\s*([aApP][mM])?$/.exec(s);if(!m)return null;var h=parseInt(m[1],10);if(h<1||h>12)return null;var mn=m[2]?parseInt(m[2],10):0;if(mn>59)return null;return{h:h,min:mn,mer:(m[3]||\"\").toUpperCase()}}\nfunction ytpMinutes54(t,mer){var h=t.h%12;if(mer===\"PM\")h+=12;return h*60+t.min}\nfunction ytpParseRange54(s){var m=/^(.+?)\\s*(?:\\u2013|\\u2014|-|\\bto\\b)\\s*(.+)$/.exec(s);if(!m)return null;var a=ytpParseTime54(m[1].trim()),b=ytpParseTime54(m[2].trim());if(!a||!b||!b.mer)return null;var close=ytpMinutes54(b,b.mer),open;\nif(a.mer){open=ytpMinutes54(a,a.mer)}\nelse{open=ytpMinutes54(a,b.mer);if(open>close){var f=ytpMinutes54(a,b.mer===\"AM\"?\"PM\":\"AM\");if(f<close)open=f}if(open>close)return null;if(open===close)return[[open,open+1440]]}\nif(close<=open)close+=1440;return[[open,close]]}\nvar YTP_DAYS54={monday:0,mon:0,mo:0,tuesday:1,tue:1,wednesday:2,wed:2,thursday:3,thu:3,friday:4,fri:4,fr:4,saturday:5,sat:5,sunday:6,sun:6};\nfunction ytpParseDay54(s){if(typeof s!==\"string\")return null;var t=s.trim();if(!t)return null;var low=t.toLowerCase();\nif(/^(emergency:\\s*)?24\\/7$/.test(low)||/^24 hours daily, \\d+ days$/.test(low))return{all24:true};\nif(low.indexOf(\"office hours:\")===0){t=t.slice(t.indexOf(\":\")+1).trim();low=t.toLowerCase()}\nt=t.replace(/\\(weekend not stated\\)\\s*$/,\"\").trim();low=t.toLowerCase();\nvar m=/^([a-z]+)\\s*(?:[-\\u2013]\\s*([a-z]+))?\\s*[,:]?\\s*(.+)$/.exec(low);if(!m)return null;\nvar d1=YTP_DAYS54[m[1]];if(d1===undefined)return null;var days=[d1];\nif(m[2]){var d2=YTP_DAYS54[m[2]];if(d2===undefined||d2<d1)return null;days=[];for(var d=d1;d<=d2;d++)days.push(d)}\nvar rest=m[3].trim(),ranges;\nif(rest===\"closed\")ranges=[];\nelse if(rest===\"open 24 hours\")ranges=[[0,1440]];\nelse{ranges=[];var parts=rest.split(\",\");for(var i=0;i<parts.length;i++){var r=ytpParseRange54(parts[i].trim());if(!r)return null;for(var j=0;j<r.length;j++)ranges.push(r[j])}}\nreturn{days:days,ranges:ranges}}\nfunction ytpParseWeek54(list){if(!list||!list.length)return null;var byDay={},sawDay=false,i,j;\nfor(i=0;i<list.length;i++){var p=ytpParseDay54(list[i]);if(!p)return null;if(p.all24)continue;sawDay=true;for(j=0;j<p.days.length;j++){if(byDay[p.days[j]])return null;byDay[p.days[j]]=p.ranges}}\nif(!sawDay){var o={};for(i=0;i<7;i++)o[i]=[[0,1440]];return o}\nfor(i=0;i<7;i++)if(!byDay[i])return null;return byDay}\nfunction ytpFmtMin54(m){m=((m%1440)+1440)%1440;var h=Math.floor(m/60),mm=m%60,h12=h%12;if(h12===0)h12=12;return h12+(mm?\":\"+(\"0\"+mm).slice(-2):\"\")+(h>=12?\" PM\":\" AM\")}\nfunction ytpOpenNow54(list,tz){var wk=ytpParseWeek54(list);if(!wk)return null;var now;\ntry{var parts=new Intl.DateTimeFormat(\"en-US\",{timeZone:tz,weekday:\"short\",hour:\"2-digit\",minute:\"2-digit\",hourCycle:\"h23\"}).formatToParts(new Date());var o={};for(var i=0;i<parts.length;i++)o[parts[i].type]=parts[i].value;var dm={Mon:0,Tue:1,Wed:2,Thu:3,Fri:4,Sat:5,Sun:6};if(dm[o.weekday]===undefined)return null;now={day:dm[o.weekday],min:(parseInt(o.hour,10)%24)*60+parseInt(o.minute,10)}}catch(e){return null}\nvar open=false,r,i,today=wk[now.day];\nfor(i=0;i<today.length;i++){r=today[i];if(now.min>=r[0]&&now.min<r[1])open=true}\nif(!open){var y=wk[(now.day+6)%7];for(i=0;i<y.length;i++){r=y[i];if(r[1]>1440&&now.min<r[1]-1440)open=true}}\nvar txt;if(!today.length)txt=\"Closed today\";else if(today.length===1&&today[0][0]===0&&today[0][1]===1440)txt=\"Open 24 hours\";else txt=\"Today: \"+today.map(function(r){return ytpFmtMin54(r[0])+\" \\u2013 \"+ytpFmtMin54(r[1])}).join(\", \");\nreturn{open:open,label:open?\"Open now\":\"Closed\",today:txt}}\n(function(){var el=document.getElementById(\"ytp-opennow\");if(!el)return;var items=document.querySelectorAll(\".hourslist li\");var list=[];for(var i=0;i<items.length;i++)list.push(items[i].textContent);var st=ytpOpenNow54(list,el.getAttribute(\"data-tz\"));if(!st)return;el.innerHTML='<span class=\"'+(st.open?\"on-open\":\"on-closed\")+'\">'+st.label+'</span> <span class=\"on-today\">'+st.today+\"</span>\";el.hidden=false})();\n\n</script>";
const RENTRACK_SCRIPT = "<script>\n/* Renaud featured tracking.\n * Companion to the existing v5.5 GoatCounter action events script.\n * This file does not replace v5.5; it adds the Renaud partner events:\n *   Event 1  renaud-card-view   /_events/renaud-card-view/<surface>/<host slug>\n *   Event 2  renaud-card-click  /_events/renaud-card-click/<surface>/<host slug>\n *   Event 3  renaud-call        /_events/renaud-call/<surface>/<page slug>\n *   Supp.    renaud-website     /_events/renaud-website/ytp-profile/<page slug>\n * Surface values: ytp-card-category, ytp-card-listing, ytp-hub, ytp-profile.\n * The generator should set data-surface on the card (authoritative).\n * The inference below is a fallback only. No personal data is sent.\n * Honest limits: a card view means the card entered the viewport at\n * 50 percent visibility once; it does not prove anyone read it.\n * A call event means the tel link was tapped, not that a call connected.\n */\n(function () {\n  var PROFILE_SLUG = \"natural-skincare/renaud-naturals-loveland\";\n\n  function fire(path) {\n    try {\n      if (!window.goatcounter || !window.goatcounter.count) return;\n      window.goatcounter.count({ path: path, event: true, title: path });\n    } catch (e) {}\n  }\n\n  function pageSlug() {\n    return window.location.pathname.replace(/^\\/+|\\/+$/g, \"\");\n  }\n\n  function inferSurface(slug) {\n    /* Town hub or state page: /colorado/westminster/ or /colorado/ */\n    if (/^[a-z-]+\\/[a-z-]+$/.test(slug) && slug.indexOf(\"/\") === slug.lastIndexOf(\"/\")) {\n      var first = slug.split(\"/\")[0];\n      /* Single listing pages also have two segments, so hubs are matched\n       * by the state segment list used by the generator. When in doubt,\n       * the generator supplied data-surface wins and this never runs. */\n      var states = [\"colorado\", \"arizona\", \"california\", \"texas\", \"florida\", \"nevada\", \"utah\", \"wyoming\", \"montana\", \"idaho\", \"oregon\", \"washington\", \"new-mexico\", \"oklahoma\", \"kansas\", \"nebraska\", \"south-dakota\", \"north-dakota\", \"minnesota\", \"iowa\", \"missouri\", \"arkansas\", \"wisconsin\", \"illinois\", \"michigan\", \"indiana\", \"ohio\", \"kentucky\", \"tennessee\", \"louisiana\", \"mississippi\", \"alabama\", \"georgia\", \"alaska\", \"hawaii\", \"puerto-rico\"];\n      if (states.indexOf(first) !== -1) return \"ytp-hub\";\n      return \"ytp-card-listing\";\n    }\n    /* Category in town: /med-spas/colorado/westminster/ (3 segments) */\n    if (slug.split(\"/\").length === 3) return \"ytp-card-category\";\n    return \"ytp-card-listing\";\n  }\n\n  function firstTouchSrc(value) {\n    try {\n      var k = \"ytp_renaud_src\";\n      if (!window.sessionStorage.getItem(k)) window.sessionStorage.setItem(k, value);\n      return window.sessionStorage.getItem(k);\n    } catch (e) {\n      return value;\n    }\n  }\n\n  function arrivingSrc() {\n    try {\n      var p = new URLSearchParams(window.location.search);\n      return p.get(\"src\") || null;\n    } catch (e) {\n      return null;\n    }\n  }\n\n  function init() {\n    var slug = pageSlug();\n    if (!slug) return;\n\n    /* Events 1, 2, and the card leg of Event 3: the partner card. */\n    var card = document.querySelector('article.partnercard[data-profile=\"renaud-naturals\"]');\n    if (card) {\n      var surface = card.getAttribute(\"data-surface\") || inferSurface(slug);\n\n      if (\"IntersectionObserver\" in window) {\n        var seen = false;\n        var io = new IntersectionObserver(function (entries) {\n          for (var i = 0; i < entries.length; i++) {\n            if (entries[i].isIntersecting && !seen) {\n              seen = true;\n              fire(\"/_events/renaud-card-view/\" + surface + \"/\" + slug);\n              io.disconnect();\n            }\n          }\n        }, { threshold: 0.5 });\n        io.observe(card);\n      }\n\n      card.addEventListener(\"click\", function (ev) {\n        var a = ev.target && ev.target.closest ? ev.target.closest(\"a\") : null;\n        if (!a) return;\n        var h = a.getAttribute(\"href\") || \"\";\n        if (h.indexOf(\"tel:\") === 0) {\n          fire(\"/_events/renaud-call/\" + surface + \"/\" + slug);\n          return;\n        }\n        if (h.indexOf(\"/natural-skincare/renaud-naturals-loveland/\") === 0) {\n          firstTouchSrc(surface);\n          fire(\"/_events/renaud-card-click/\" + surface + \"/\" + slug);\n        }\n      });\n    }\n\n    /* Profile page bindings: Event 3 profile leg and S2 website outbound. */\n    if (slug === PROFILE_SLUG) {\n      var src = arrivingSrc();\n      if (src) firstTouchSrc(src);\n      document.addEventListener(\"click\", function (ev) {\n        var a = ev.target && ev.target.closest ? ev.target.closest(\"a\") : null;\n        if (!a) return;\n        var h = a.getAttribute(\"href\") || \"\";\n        if (a.hasAttribute(\"data-renaud-call\") || h.indexOf(\"tel:+19706671433\") === 0) {\n          fire(\"/_events/renaud-call/ytp-profile/\" + slug);\n          return;\n        }\n        if (a.hasAttribute(\"data-renaud-website\") || h.indexOf(\"https://renaudnaturals.com\") === 0) {\n          fire(\"/_events/renaud-website/ytp-profile/\" + slug);\n        }\n      });\n    }\n  }\n\n  if (document.readyState === \"loading\") {\n    document.addEventListener(\"DOMContentLoaded\", init);\n  } else {\n    init();\n  }\n})();\n\n</script>";
const HEAD_REFERENCE = "<title>Cuevas Brothers Plumbers in Westminster, CO</title><meta name=\"description\" content=\"Cuevas Brothers Plumbers is a plumber in Westminster, Colorado. It has a 4.9-star Google rating from 267 reviews. Call (970) 367-1649 or visit 5040 W 92nd.\"><link rel=\"canonical\" href=\"https://yourtownpros.com/plumbers/cuevas-brothers-plumbers-westminster/\"><link rel=\"icon\" href=\"/favicon.svg\" type=\"image/svg+xml\"><link rel=\"icon\" href=\"/favicon.ico\" sizes=\"32x32\"><link rel=\"apple-touch-icon\" href=\"/apple-touch-icon.png\"><meta property=\"og:type\" content=\"website\"><meta property=\"og:site_name\" content=\"YourTownPros\"><meta property=\"og:title\" content=\"Cuevas Brothers Plumbers in Westminster, CO\"><meta property=\"og:description\" content=\"Cuevas Brothers Plumbers is a plumber in Westminster, Colorado. It has a 4.9-star Google rating from 267 reviews. Call (970) 367-1649 or visit 5040 W 92nd.\"><meta property=\"og:url\" content=\"https://yourtownpros.com/plumbers/cuevas-brothers-plumbers-westminster/\"><meta property=\"og:image\" content=\"https://images.unsplash.com/photo-1607472586893-edb57bdc0e39?auto=format&fit=crop&w=1200&h=630&q=70\"><meta name=\"twitter:card\" content=\"summary_large_image\"><link rel=\"stylesheet\" href=\"https://cdn.jsdelivr.net/npm/leaflet@1.9.4/dist/leaflet.css\" integrity=\"sha256-p4NxAoJBhIIN+hmNHrzRCf9tD/miZyoHS5obTRR9BMY=\" crossorigin=\"\">";

// YourTownPros listing renderer: one template, one D1 row, byte-close to the
// static page for the same business. Pure functions over a D1-shaped db
// interface (prepare(sql).bind(...).first() / .all()), so the same code runs
// in the Worker (env.DB) and locally (local-db.mjs over node:sqlite).
//
// Render read budget (brief section 3): redirect lookup 1, listing 1, trade 1,
// state 1, similar up to 5, partner card up to 1. About 10 rows, under the 30
// row cap. No query in this file scans: every lookup is a PK or index hit,
// and radius search never happens at render time (similar_pros is precomputed
// by the loader using the cell index design in schema.sql).


// The static generator serialises JSON the Python way: ", " between items and
// ": " after keys. Match it exactly or every JSON block diffs.
function pyJson(v) {
  if (v === null || v === undefined) return "null";
  if (typeof v === "number" || typeof v === "boolean") return JSON.stringify(v);
  if (typeof v === "string") return JSON.stringify(v);
  if (Array.isArray(v)) return "[" + v.map(pyJson).join(", ") + "]";
  return "{" + Object.entries(v).map(([k, x]) => `${JSON.stringify(k)}: ${pyJson(x)}`).join(", ") + "}";
}

// Python html.escape(quote=True) and urllib.parse.quote(safe="") semantics,
// which is what the static generator uses for names in text, attributes and
// claim links (apostrophes become &#x27; in HTML and %27 in URLs).
const esc = (s) => String(s ?? "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
  .replace(/"/g, "&quot;").replace(/'/g, "&#x27;");
const escAttr = esc;
const enc = (s) => encodeURIComponent(String(s ?? ""))
  .replace(/'/g, "%27").replace(/\(/g, "%28").replace(/\)/g, "%29").replace(/\*/g, "%2A").replace(/!/g, "%21");
const fmtRating = (r) => Number(r).toFixed(1); // hero stars always print one decimal
const fmtRatingCard = (r) => String(Number(r)); // rail cards print 5, not 5.0
// Five-glyph star display rounded to the nearest half: 4.2 prints four full
// and one empty, 4.5 four full and one half, 4.8 five full.
const stars = (r) => {
  const halves = Math.round(r * 2);
  const full = Math.floor(halves / 2), half = halves % 2;
  return "★".repeat(full) + (half ? "⯨" : "") + "☆".repeat(5 - full - half);
};

// Street address as the meta description prints it: unit dropped, trailing
// street-type word dropped ('5040 W 92nd Ave #8600' becomes '5040 W 92nd').
const STREET_SUFFIX = new Set(["Ave", "Avenue", "St", "Street", "Blvd", "Boulevard", "Dr", "Drive",
  "Rd", "Road", "Ln", "Lane", "Ct", "Court", "Way", "Pl", "Place", "Cir", "Circle", "Hwy", "Highway",
  "Pkwy", "Parkway", "Trl", "Trail"]);
function descAddress(address) {
  if (!address) return null;
  const noUnit = address.split("#")[0].trim().replace(/,$/, "");
  const words = noUnit.split(/\s+/);
  if (words.length > 3 && STREET_SUFFIX.has(words[words.length - 1])) words.pop();
  return words.join(" ");
}

function head(l, t, st) {
  // Title, description and og:title are listing data (their wording depends
  // on rating, address and phone in ways the data files do not fully
  // determine), so the loader harvests them verbatim from the static page.
  const base = `${esc(l.name)} in ${esc(l.city)}, ${l.state}`;
  const title = l.page_title || (l.rating != null ? base : `${base}: Phone Number | YourTownPros`);
  const ogTitle = l.og_title || (l.rating != null ? base : `${base}: Phone Number`);
  let desc = l.meta_desc;
  if (!desc) {
    desc = `${l.name} is a ${t.singular} in ${l.city}, ${st.name}.`;
    if (l.rating != null) {
      desc += ` It has a ${fmtRating(l.rating)}-star Google rating from ${l.review_count} reviews.`;
      desc += ` Call ${l.phone} or visit ${descAddress(l.address)}.`;
    } else if (l.phone) {
      desc += ` Call ${l.phone}. Owners can claim this free listing.`;
    }
  }
  const url = `https://yourtownpros.com/${l.path}/`;
  return `<title>${title}</title><meta name="description" content="${desc}">` +
    `<link rel="canonical" href="${url}">` +
    `<link rel="icon" href="/favicon.svg" type="image/svg+xml"><link rel="icon" href="/favicon.ico" sizes="32x32">` +
    `<link rel="apple-touch-icon" href="/apple-touch-icon.png">` +
    `<meta property="og:type" content="website"><meta property="og:site_name" content="YourTownPros">` +
    `<meta property="og:title" content="${ogTitle}"><meta property="og:description" content="${desc}">` +
    `<meta property="og:url" content="${url}"><meta property="og:image" content="${l.image_url || t.og_image}">` +
    `<meta name="twitter:card" content="summary_large_image">` +
    `<link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/leaflet@1.9.4/dist/leaflet.css" integrity="sha256-p4NxAoJBhIIN+hmNHrzRCf9tD/miZyoHS5obTRR9BMY=" crossorigin="">`;
}

function crumb(l, t, st) {
  const head = `<main class="wrap"><div class="crumb"><a href="/">Home</a> / <a href="/${l.trade_slug}/">${esc(t.label)}</a> / ` +
    `<a href="/${l.trade_slug}/${l.state_slug}/">${esc(st.name)}</a> / `;
  if (!l.crumb_linked) return head + `${esc(l.city)}</div>`;
  return head +
    `<a href="/${l.trade_slug}/${l.state_slug}/${l.city_slug}/" title="${escAttr(t.label)} in ${escAttr(st.name)}">${esc(t.label)} in ${esc(l.city)}</a></div>`;
}

function hero(l, t) {
  const base = String(l.image_url || t.og_image).split("?")[0];
  const img = (w) => `${base}?auto=format&amp;fit=crop&amp;w=${w}&amp;q=60`;
  return `<div class="bizhero57"><img class="photoband-img" src="${img(1200)}" ` +
    `srcset="${img(480)} 480w, ${img(828)} 828w, ${img(1200)} 1200w" sizes="100vw" width="1200" height="180" ` +
    `fetchpriority="high" alt="Stock photo: ${escAttr(t.phrase)} in ${escAttr(l.city)}, ${l.state}"></div>`;
}

function h1block(l, t) {
  let s = `<h1>${esc(l.name)}</h1><span class="pill">${esc(t.label)}</span><span class="pill">${esc(l.city)}, ${l.state}</span>`;
  if (l.rating != null && l.review_count != null) s += `<p class="stars">${stars(l.rating)} ${l.rating_text || fmtRatingCard(l.rating)} · ${l.review_count} reviews <span class="gsrc">Google rating</span></p>`;
  else if (l.rating != null) s += `<p class="stars">${stars(l.rating)} ${l.rating_text || fmtRatingCard(l.rating)} <span class="gsrc">Google rating</span></p>`;
  else if (l.review_count != null) s += `<p class="stars">${l.review_count} reviews <span class="gsrc">Google rating</span></p>`;
  return s;
}

function about(l, t, st) {
  // Enriched listings replace the About block with owner/Places copy and,
  // when chips exist, the amenities block. Both are harvested verbatim.
  if (l.from_business) {
    return `<h2>From this business</h2><p>${l.from_business}</p>` +
      `<p class="listed">Listed in the YourTownPros directory with publicly available information. To book, call the number above.</p>`;
  }
  return `<h2>About this listing</h2><p>${esc(l.name)} is a ${esc(t.phrase)} business in ${esc(l.city)}, ${esc(st.name)}, ` +
    `listed in the YourTownPros directory with publicly available information. To book, call the number above.</p>`;
}

function amen(l) {
  return l.amen_html ? `<h2>Amenities and services</h2><div class="amen57">${l.amen_html}</div>` : "";
}

// biz-data addresses sometimes already end with ', City, ST' or ', City, ST ZIP'.
// fullAddress never duplicates the suffix; streetParts splits it back out for
// the JSON-LD streetAddress and postalCode fields.
// The location block's directions link tolerates a trailing ZIP in the
// stored suffix; the contact card's link appends the suffix unconditionally
// (it visibly duplicates on addresses that already carry it; that is what
// the static pages print). Two rules, two links, both intentional here.
function fullAddress(l) {
  if (!l.address) return null;
  const suf = `, ${l.city}, ${l.state}`;
  if (l.address.endsWith(suf)) return l.address;
  if (new RegExp(`, ${l.city}, ${l.state} \\d{5}$`).test(l.address)) return l.address;
  return l.address + suf;
}
// The map block prints the address without its ZIP. Its suffix rule differs
// from the directions link in one case: an address ending in just ', City'
// takes only ', ST' here, while the directions link appends ', City, ST'.
function lmapAddress(l) {
  const a = l.address.replace(/, ([A-Z]{2}) \d{5}$/, ", $1");
  const suf = `, ${l.city}, ${l.state}`;
  if (a.endsWith(suf)) return a;
  if (a.endsWith(`, ${l.city}`)) return `${a}, ${l.state}`;
  return a + suf;
}
function streetParts(l) {
  if (!l.address) return { street: null, zip: null };
  if (l.address === `${l.city}, ${l.state}`) return { street: null, zip: null };
  const m = new RegExp(`^(.*), ${l.city}(?:, ${l.state}(?: (\\d{5}))?)?$`).exec(l.address);
  if (!m) return { street: l.address, zip: null };
  return { street: m[1], zip: m[2] || null };
}
function directionsUrl(l) {
  const dest = l.address ? fullAddress(l) : `${l.city}, ${l.state}`;
  return `https://www.google.com/maps/dir/?api=1&destination=${enc(dest)}`;
}
function contactDirectionsUrl(l) {
  return `https://www.google.com/maps/dir/?api=1&destination=${enc(`${l.address}, ${l.city}, ${l.state}`)}`;
}

function lochrs(l) {
  let left;
  if (l.pin_source === "pin") {
    const data = { mode: "pin", lat: l.lat, lng: l.lng, name: l.name, addr: lmapAddress(l) };
    left = `<div><div class="lmapwrap"><div id="ytp-lmap" class="lmap"></div></div>` +
      `<p><a href="${directionsUrl(l)}">Get directions</a></p>` +
      `<script type="application/json" id="ytp-lmap-data">${pyJson(data)}</script></div>`;
  } else {
    const data = { mode: "city", lat: l.lat, lng: l.lng, city: `${l.city}, ${l.state}` };
    left = `<div><div class="lmapwrap"><div id="ytp-lmap" class="lmap"></div>` +
      `<p class="mapcap">Business pins appear here as addresses are verified.</p></div>` +
      (l.address ? `<p><a href="https://www.google.com/maps/dir/?api=1&destination=${enc(l.address)}">Get directions</a></p>` : "") +
      `<script type="application/json" id="ytp-lmap-data">${pyJson(data)}</script></div>`;
  }
  let right = `<div><p>${l.address ? esc(l.address) : `${esc(l.city)}, ${l.state}`}</p>`;
  if (l.hours_json) {
    const items = JSON.parse(l.hours_json).map((h) => `<li>${esc(h)}</li>`).join("");
    right += `<p class="opennow" id="ytp-opennow" data-tz="${l.hours_tz}" hidden></p><ul class="hourslist">${items}</ul>`;
  } else {
    right += `<p class="hoursnone"><strong>Hours not listed yet</strong></p>` +
      `<p class="listed">Is this your business? <a href="/claim/?business=${l.path}&name=${enc(l.name)}">Claim this free listing</a> to add your hours.</p>`;
  }
  right += `</div>`;
  return `<div class="lochrs57">${left}${right}</div>`;
}

function feat(l, t) {
  return `<div class="feat"><div class="k">Sponsored · Featured spot open</div>` +
    `<h2>One ${esc(t.phrase)} business in ${esc(l.city)} gets this spot</h2>` +
    `<p style="margin:0">The featured business in ${esc(l.city)} appears first here, and gets an online booking button on its listing so customers can book without calling. This placement is exclusive to one business per town.</p></div>`;
}

function matchopen(l, t) {
  return `<div class="match" id="match"><h2>Get matched with a ${esc(l.city)} ${esc(t.phrase)} pro</h2>` +
    `<p style="margin:0">Tell us what you need. Your request comes to YourTownPros first: we contact ${esc(l.name)} about it, and if they cannot take the job, we match you with another ${esc(l.city)} ${esc(t.phrase)} pro instead. Free for customers, and no obligation.</p>\n` +
    `<form action="https://formsubmit.co/yourtownpros@gmail.com" method="POST" id="ytp-match-form" data-match-slug="${l.path}" data-match-source="listing">\n` +
    `<input type="hidden" name="_subject" value="Match request: ${escAttr(t.label)}, ${escAttr(l.city)} (via ${escAttr(l.name)} listing)"><input type="hidden" name="_template" value="table"><input type="hidden" name="_next" value="https://yourtownpros.com/match-thanks/"><div class="hpf" aria-hidden="true"><label>Company website<input type="text" name="company_website" tabindex="-1" autocomplete="off"></label></div>`;
}

function contact(l) {
  let s = `<div class="bizcard57"><h2>Contact</h2>`;
  if (l.phone) s += `<p><a class="tel" href="tel:${l.phone_digits}">Call ${esc(l.phone)}</a></p>`;
  if (l.show_website_link && l.website)
    s += `<a class="act57" href="${escAttr(l.website)}" target="_blank" rel="noopener">Visit their website</a>`;
  if (l.address)
    s += `<a class="act57" href="${contactDirectionsUrl(l)}" target="_blank" rel="noopener">Get directions</a>`;
  s += `<a class="act57" href="#match">Request a match</a></div>`;
  return s;
}

function claimstrip(l) {
  return `<div class="claimstrip">Is this your business? <a href="/claim/?business=${l.path}&name=${enc(l.name)}">Claim this free listing</a> to keep your hours, services and photos current.</div>`;
}

function jsonld(l, t) {
  const o = { "@context": "https://schema.org", "@type": t.schema_type,
    "@id": `https://yourtownpros.com/${l.path}/#business`, name: l.name,
    url: `https://yourtownpros.com/${l.path}/` };
  if (l.phone_digits) o.telephone = l.phone_digits;
  const addr = { "@type": "PostalAddress", addressLocality: l.city, addressRegion: l.state, addressCountry: "US" };
  const sp = streetParts(l);
  if (sp.street) addr.streetAddress = sp.street;
  if (sp.zip) addr.postalCode = sp.zip;
  o.address = addr;
  if (l.website && l.show_website_link) o.sameAs = [l.website];
  return `<script type="application/ld+json">${pyJson(o)}</script>`;
}

function breadcrumbSimilar(l, t, st, similars, partner) {
  const items = [
    { "@type": "ListItem", position: 1, name: "Home", item: "https://yourtownpros.com/" },
    { "@type": "ListItem", position: 2, name: t.label, item: `https://yourtownpros.com/${l.trade_slug}/` },
    { "@type": "ListItem", position: 3, name: st.name, item: `https://yourtownpros.com/${l.trade_slug}/${l.state_slug}/` },
    l.crumb_linked
      ? { "@type": "ListItem", position: 4, name: `${t.label} in ${l.city}`, item: `https://yourtownpros.com/${l.trade_slug}/${l.state_slug}/${l.city_slug}/` }
      : { "@type": "ListItem", position: 4, name: l.city, item: `https://yourtownpros.com/${l.state_slug}/${l.city_slug}/` },
    { "@type": "ListItem", position: 5, name: l.name, item: `https://yourtownpros.com/${l.path}/` },
  ];
  const bc = { "@context": "https://schema.org", "@type": "BreadcrumbList", itemListElement: items };
  let s = `<script type="application/ld+json">${pyJson(bc)}</script>`;
  if (similars.length === 0) {
    // An empty rail omits the whole similar block on the static pages.
    if (partner) s += partnerCard(partner);
    return s;
  }
  const cards = similars.map((x) => {
    let c = `<div class="card"><h3><a href="/${x.path}/">${esc(x.name)}</a></h3>`;
    if (x.rating != null && x.review_count != null) c += `<div class="stars">${stars(x.rating)} ${x.rating_text || fmtRatingCard(x.rating)} · ${x.review_count} reviews <span class="gsrc">Google rating</span></div>`;
    else if (x.rating != null) c += `<div class="stars">${stars(x.rating)} ${x.rating_text || fmtRatingCard(x.rating)} <span class="gsrc">Google rating</span></div>`;
    else if (x.review_count != null) c += `<div class="stars">${x.review_count} reviews <span class="gsrc">Google rating</span></div>`;
    c += `<div class="listed">Listed in ${esc(x.city)}</div>`;
    if (x.address) c += `<div class="meta">${esc(x.address)}</div>`;
    else c += `<div class="meta">${esc(x.city)}, ${x.state}</div>`;
    if (x.phone) c += `<div class="meta">${esc(x.phone)}</div>`;
    c += `<div class="meta cardreq"><a href="/${x.path}/?src=card#match">Request this pro</a></div></div>`;
    return c;
  }).join("");
  s += `<div class="similar"><h2>Similar pros nearby</h2><div class="grid">${cards}</div>` +
    `<p><a href="/${l.trade_slug}/${l.state_slug}/">More ${esc(t.label)} in ${esc(st.name)}</a> · ` +
    `<a href="/${l.state_slug}/${l.city_slug}/">All local businesses in ${esc(l.city)}, ${l.state}</a></p></div>`;
  if (partner) s += partnerCard(partner);
  return s;
}

function partnerCard(partner) {
  return `<article class="partnercard" data-profile="${partner.partner_id}" data-slug="${partner.profile_path}" data-surface="ytp-card-listing">` +
    `<p class="sponline">Sponsored · Featured partner</p><h3>${esc(partner.name)}</h3><p>${esc(partner.blurb)}</p>` +
    `<p><a href="/${partner.profile_path}/?src=ytp-card-listing">${esc(partner.link_text)}</a></p></article>`;
}

async function renderListing(db, path) {
  const l = await db.prepare("SELECT * FROM listings WHERE path = ?").bind(path).first();
  if (!l) return null;
  const t = await db.prepare("SELECT * FROM trades WHERE trade_slug = ?").bind(l.trade_slug).first();
  const st = await db.prepare("SELECT * FROM states WHERE state = ?").bind(l.state).first();
  const sim = await db.prepare(
    "SELECT x.* FROM similar_pros s JOIN listings x ON x.path = s.similar_path WHERE s.path = ? ORDER BY s.rank")
    .bind(path).all();
  const pc = await db.prepare(
    "SELECT p.* FROM listing_partner_cards c JOIN partner_cards p ON p.partner_id = c.partner_id" +
    " WHERE c.path = ? AND p.trade_slug = ? AND p.active = 1 LIMIT 1").bind(path, l.trade_slug).first();

  let html = TEMPLATE;
  const slots = {
    "{{HEAD}}": head(l, t, st),
    "{{CRUMB}}": crumb(l, t, st),
    "{{HERO}}": hero(l, t),
    "{{H1BLOCK}}": h1block(l, t),
    "{{ABOUT}}": about(l, t, st),
    "{{AMEN}}": amen(l),
    "{{LOCHRS}}": lochrs(l),
    "{{FEAT}}": feat(l, t),
    "{{MATCHOPEN}}": matchopen(l, t),
    "{{PLACEHOLDER}}": escAttr(t.service_placeholder || ""),
    "{{CONTACT}}": contact(l),
    "{{CLAIMSTRIP}}": claimstrip(l),
    "{{JSONLD}}": jsonld(l, t),
    "{{BREADCRUMB_SIMILAR}}": breadcrumbSimilar(l, t, st, sim.results || [], pc),
    "{{OPENNOW}}": l.hours_json ? OPENNOW_SCRIPT : "",
    "{{RENTRACK}}": pc ? RENTRACK_SCRIPT : "",
  };
  for (const [k, v] of Object.entries(slots)) html = html.split(k).join(v);
  html = html.split("{{PATH}}").join(l.path);
  html = html.split("{{TRADE_SLUG}}").join(l.trade_slug);
  html = html.split("{{CITY}}").join(l.city);
  return html;
}

async function lookupRedirect(db, path) {
  const r = await db.prepare("SELECT to_path, status FROM redirects WHERE from_path = ?").bind(path).first();
  return r || null;
}

// Cloudflare Worker entry for listing pages (gate d). NOT deployed by this
// build; deployment is an account step listed in ACCOUNT-STEPS.md.
//
// Routing contract (brief sections 1 and 2): one Worker route per trade
// matches the two-segment listing pattern /<trade>/<business-slug>-<town>/.
// The Worker re-checks the path shape itself and passes anything that is not
// a true listing straight through to the static origin, so a misfire costs
// one pass-through, never a wrong page. Every route is set FAIL OPEN in the
// dashboard, so hitting the daily request cap bypasses the Worker instead of
// erroring (brief section 3). Bot features stay OFF on the zone (brief
// section 6); nothing in this Worker challenges any user agent.


const LISTING_PATH = /^\/([a-z0-9-]+)\/([a-z0-9-]+)\/?$/;

// The _headers general rule for rendered pages (the Pages _headers file does
// not apply to Worker responses, so the Worker sets the same values itself).
const PAGE_HEADERS = {
  "Content-Type": "text/html; charset=utf-8",
  "Strict-Transport-Security": "max-age=31536000; includeSubDomains",
  "X-Content-Type-Options": "nosniff",
  "Referrer-Policy": "strict-origin-when-cross-origin",
  "X-Frame-Options": "SAMEORIGIN",
  "Cache-Control": "public, max-age=0, must-revalidate",
};

export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);
    const m = LISTING_PATH.exec(url.pathname);
    if (!m) return fetch(request); // not listing-shaped: static origin serves it
    const path = `${m[1]}/${m[2]}`;

    const redirect = await lookupRedirect(env.DB, path);
    if (redirect) {
      return Response.redirect(`https://${url.host}/${redirect.to_path}/`, redirect.status || 301);
    }
    const html = await renderListing(env.DB, path);
    if (html === null) return fetch(request); // unknown slug: pass through (static 404 there)
    return new Response(html, { headers: PAGE_HEADERS });
  },
};
